"""Demo 2: degenerate amplitude -> infinite but density-zero exceptions."""
from __future__ import annotations
import math
from typing import Callable, List

def is_square(n: int) -> bool:
    r = math.isqrt(n)
    return n >= 0 and r * r == n

def sq_coeff(n: int) -> float:
    return 0.0 if is_square(n) else ((-1) ** n) * 1.0

def alternation_exceptions(a: List[float]) -> List[int]:
    return [n for n in range(len(a) - 1) if a[n] * a[n + 1] >= 0.0]

def density(pred: Callable[[int], bool], N: int) -> float:
    return sum(1 for n in range(N) if pred(n)) / N if N else 0.0

def run(N: int = 2000) -> None:
    a = [sq_coeff(n) for n in range(N)]
    exc = alternation_exceptions(a)
    pred = lambda n: is_square(n) or is_square(n + 1)
    print("matches theory:", exc == [n for n in range(N - 1) if pred(n)])
    for M in (100, 1000, 10000, 50000):
        print(f"N={M:6d}  density={density(pred, M):.5f}  2/sqrt(N)={2/math.sqrt(M):.5f}")

if __name__ == "__main__":
    run()

